class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def distance_k(root_arr, target, k):
    root = build_tree(root_arr)

    parent = {}
    target_node = [None]

    def map_parents(node, par):
        if node is None:
            return
        parent[node] = par
        if node.val == target:
            target_node[0] = node
        map_parents(node.left, node)
        map_parents(node.right, node)

    map_parents(root, None)

    visited = {target_node[0]}
    queue = [target_node[0]]
    distance = 0
    while queue and distance < k:
        next_queue = []
        for node in queue:
            for neighbor in (node.left, node.right, parent[node]):
                if neighbor is not None and neighbor not in visited:
                    visited.add(neighbor)
                    next_queue.append(neighbor)
        queue = next_queue
        distance += 1

    return sorted(node.val for node in queue)

